<?php
declare(strict_types=1);defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\CMS\Form\Field\ListField;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\Database\DatabaseInterface;use Joomla\Database\ParameterType;
class JFormFieldEvent extends ListField{protected$type='Event';protected function getOptions():array{$o=parent::getOptions();$id=(int)$this->form->getValue('project_id',$this->group);if($id<1)return$o;$db=Factory::getContainer()->get(DatabaseInterface::class);$q=$db->getQuery(true)->select(['event.event_code','MAX(event.event_name_key) AS name_key'])->from($db->quoteName('#__joomleague_match_event','event'))->innerJoin($db->quoteName('#__joomleague_project_match','match').' ON match.id=event.match_id AND match.published=1')->innerJoin($db->quoteName('#__joomleague_match_result','result')." ON result.match_id=match.id AND result.status_code='final'")->where('event.project_id=:project')->where('event.published=1')->where('(event.primary_person_id IS NOT NULL OR event.match_participant_id IS NOT NULL OR event.source_match_actor_role_id IS NOT NULL)')->group('event.event_code')->order('event.event_code ASC')->bind(':project',$id,ParameterType::INTEGER);Factory::getLanguage()->load('com_joomleague',JPATH_SITE);foreach($db->setQuery($q)->loadObjectList()as$r)$o[]=HTMLHelper::_('select.option',(string)$r->event_code,Text::_((string)$r->name_key));return$o;}}
